def use_clean_for_untouched_sidebars(apps, schema_editor):
    """Move only companies that never chose a sidebar over to Clean.

    A saved style still wins: the branding form writes a ``branding.update``
    audit row, and finishing wizard step 3 records step 3 in
    ``setup_completed_steps``. Companies with either marker keep whatever
    they picked, including Classic Black.
    """
    Organization = apps.get_model('attendance', 'Organization')
    AuditLog = apps.get_model('attendance', 'AuditLog')

    untouched = Organization.objects.filter(
        nav_style='black',
        nav_bg_color='#0A0A0A',
        nav_highlight_style='pill',
        nav_highlight_source='auto',
        nav_highlight_color='#0A0A0A',
    )
    for organization in untouched.iterator():
        if 3 in (organization.setup_completed_steps or []):
            continue
        if AuditLog.objects.filter(
            organization_id=organization.pk, action='branding.update'
        ).exists():
            continue
        organization.nav_style = 'clean'
        organization.save(update_fields=['nav_style'])


